documents = {
    101: {"owner": "A", "text": "Tài liệu thử A"},
    202: {"owner": "B", "text": "Tài liệu thử B"},
}

def read_document(current_user, document_id):
    document = documents.get(document_id)
    if document is None or document["owner"] != current_user:
        raise PermissionError("Không được truy cập")
    return document["text"]

assert read_document("A", 101) == "Tài liệu thử A"
assert read_document("B", 202) == "Tài liệu thử B"
for user, document_id in [("B", 101), ("A", 202)]:
    try:
        read_document(user, document_id)
    except PermissionError:
        pass
    else:
        raise AssertionError("Thiếu kiểm tra quyền")
print("Hai lượt đọc đúng quyền; hai lượt đọc chéo bị từ chối")

def encode(data):
    return bytes(((value + 3) & 0xff) ^ 0x2a for value in data)

def decode(data):
    return bytes(((value ^ 0x2a) - 3) & 0xff for value in data)

sample = b"LAB"
encoded = encode(sample)
assert decode(encoded) == sample
assert decode(encode(bytes(range(256)))) == bytes(range(256))
print(encoded.hex())
print(decode(encoded).decode("ascii"))
